pub fn encrypt (key : & [u8] , decrypted : & [u8]) -> Result < Encrypted > { let key = Key :: from_slice (key) ; let cipher = XChaCha20Poly1305 :: new (key) ; let mut nonce_bytes = [0u8 ; 24] ; rand :: thread_rng () . fill_bytes (& mut nonce_bytes) ; let nonce = XNonce :: from (nonce_bytes) ; let encrypted = cipher . encrypt (& nonce , decrypted) . map_err (| _ | HttpError :: ChaCha20Poly1305) ? ; Ok (Encrypted { ciphertext : encrypted , nonce : nonce_bytes . to_vec () , }) }